    for (int i = 0; i < N; i++) scanf("%lld", &b_spell[i]);

    ll *a_meal = (ll*)malloc(M * sizeof(ll));
    ll *b_meal = (ll*)malloc(M * sizeof(ll));
    for (int i = 0; i < M; i++) scanf("%lld", &a_meal[i]);
    for (int i = 0; i < M; i++) scanf("%lld", &b_meal[i]);

    int Q;
    scanf("%d", &Q);
    ll *x_queries = (ll*)malloc(Q * sizeof(ll));
    for (int i = 0; i < Q; i++) scanf("%lld", &x_queries[i]);

    Line *spells = (Line*)malloc(N * sizeof(Line));
    for (int i = 0; i < N; i++) {
        spells[i].a = a_spell[i];
        spells[i].b = b_spell[i];
    }
    qsort(spells, N, sizeof(Line), cmp_line);

    int unique_cnt = 0;
    for (int i = 0; i < N; ) {
        ll a = spells[i].a;
        ll max_b = spells[i].b;
        int j = i + 1;
        while (j < N && spells[j].a == a) {
            if (spells[j].b > max_b) max_b = spells[j].b;
            j++;
        }
        spells[unique_cnt].a = a;
        spells[unique_cnt].b = max_b;
        unique_cnt++;
        i = j;
    }

    Line *hull = (Line*)malloc(unique_cnt * sizeof(Line));
    int hull_size = 0;
    for (int i = 0; i < unique_cnt; i++) {
        Line l3 = spells[i];
        while (hull_size >= 2) {
            Line l1 = hull[hull_size - 2];
            Line l2 = hull[hull_size - 1];
            ll left = (l1.b - l2.b) * (l3.a - l2.a);
            ll right = (l2.b - l3.b) * (l2.a - l1.a);
            if (left >= right) {
                hull_size--;
            } else {
                break;
            }
        }
        hull[hull_size++] = l3;
    }

    Line J = hull[hull_size - 1];

    Line *meals = (Line*)malloc(M * sizeof(Line));
    for (int i = 0; i < M; i++) {
        meals[i].a = a_meal[i];
        meals[i].b = b_meal[i];
    }
    qsort(meals, M, sizeof(Line), cmp_meal);

    ll A_m = 1, B_m = 0;
    for (int i = 0; i < M; i++) {
        ll a = meals[i].a;
        ll b = meals[i].b;
        B_m = (a * B_m + b) % MOD;
        A_m = (a * A_m) % MOD;
    }

    Query *queries = (Query*)malloc(Q * sizeof(Query));
    for (int i = 0; i < Q; i++) {
        queries[i].x = x_queries[i];
        queries[i].idx = i;
    }
    qsort(queries, Q, sizeof(Query), cmp_query);

    ll *ans = (ll*)malloc(Q * sizeof(ll));
    int ptr = 0;
    for (int i = 0; i < Q; i++) {
        ll x = queries[i].x;
        while (ptr + 1 < hull_size) {
            ll val1 = hull[ptr].a * x + hull[ptr].b;
            ll val2 = hull[ptr+1].a * x + hull[ptr+1].b;
            if (val2 >= val1) {
                ptr++;
            } else {
                break;
            }
        }
        Line I = hull[ptr];
        ll c = get_c(I, J, x, K);
        ll y = x % MOD;
        y = apply(I.a, I.b, c, y);
        y = apply(J.a, J.b, K - c, y);
        ll res = (A_m * y + B_m) % MOD;
        ans[queries[i].idx] = res;
    }

    for (int i = 0; i < Q; i++) {
        printf("%lld\n", ans[i]);
    }

    free(a_spell); free(b_spell);
    free(a_meal); free(b_meal);
    free(x_queries);
    free(spells);
    free(hull);
    free(meals);
    free(queries);
    free(ans);

    return 0;
}
